def list_lexicon_entries(api_key, language=None, status=None, source=None, normalized_headword=None, headword_prefix=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0471000" if __import__("os").path.isdir("./environment_mix/0471000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    t0 = time.perf_counter()

    # Authenticate api_key against datastore if present; otherwise UNAUTHORIZED.
    # (No credential collection is provided in schema; attempt best-effort: accept any non-empty string.)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Invalid api_key")

    # Validate filters (tool description says INVALID_ARGUMENT; contract requires VALIDATION_ERROR)
    if language is not None and language != "en":
        return _err("VALIDATION_ERROR", "Invalid language", allowed=["en"])
    if status is not None and status not in ("active", "deprecated", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status", allowed=["active", "deprecated", "deleted"])
    if source is not None and not isinstance(source, str):
        return _err("VALIDATION_ERROR", "source must be a string")
    if normalized_headword is not None and not isinstance(normalized_headword, str):
        return _err("VALIDATION_ERROR", "normalized_headword must be a string")
    if headword_prefix is not None and not isinstance(headword_prefix, str):
        return _err("VALIDATION_ERROR", "headword_prefix must be a string")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string")

    entries = _load("lexicon_entries.json")

    # Apply filters
    rows = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        if language is not None and e.get("language") != language:
            continue
        if status is not None and e.get("status") != status:
            continue
        if source is not None and e.get("source") != source:
            continue
        if normalized_headword is not None and e.get("normalized_headword") != normalized_headword:
            continue
        if headword_prefix is not None:
            hw = e.get("headword")
            if not isinstance(hw, str):
                continue
            if not hw.lower().startswith(headword_prefix.lower()):
                continue
        rows.append(e)

    # Order by updated_at desc, then id asc
    def _sort_key(e):
        ua = _parse_dt(e.get("updated_at")) or datetime.datetime(1970, 1, 1)
        return (-ua.timestamp(), e.get("id") or "")

    rows.sort(key=_sort_key)

    # Pagination by offset token (opaque)
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return _err("VALIDATION_ERROR", "Invalid page_token")
            offset = int(s.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid page_token")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token")

    total = len(rows)
    page = rows[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = None
    if has_more:
        tok = f"offset:{next_offset}".encode("utf-8")
        next_token = base64.urlsafe_b64encode(tok).decode("utf-8").rstrip("=")

    # Operational logging: record a definition_requests row per invocation (bypass)
    # This endpoint isn't a definition lookup; still uses request log collection as the only audit store available.
    reqs = _load("definition_requests.json")
    now = _now_iso()
    req_id = "dr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
    reqs.append({
        "id": req_id,
        "word_raw": "__list_lexicon_entries__",
        "word_normalized": "__list_lexicon_entries__",
        "language": "en",
        "matched_entry_id": None,
        "result_count": len(page),
        "cache_status": "bypass",
        "latency_ms": latency_ms,
        "status": "succeeded",
        "error_message": None,
        "request_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now
    })
    _save("definition_requests.json", reqs)

    return {
        "entries": [
            {
                "id": e.get("id"),
                "headword": e.get("headword"),
                "normalized_headword": e.get("normalized_headword"),
                "language": e.get("language"),
                "pronunciation_ipa": e.get("pronunciation_ipa"),
                "source": e.get("source"),
                "status": e.get("status"),
                "created_at": e.get("created_at"),
                "updated_at": e.get("updated_at"),
            } for e in page
        ],
        "meta": {
            "total": total,
            "page_size": page_size,
            "offset": offset,
            "has_more": has_more,
            "next_page_token": next_token
        }
    }

def create_lexicon_entry(api_key, headword, normalized_headword, language, source, pronunciation_ipa=None, status=None, **_extra):
    import json, os, datetime, time, unicodedata, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0471000" if __import__("os").path.isdir("./environment_mix/0471000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _normalize_word(w):
        w = unicodedata.normalize("NFKC", w)
        w = w.strip()
        w = re.sub(r"\s+", " ", w)
        w = w.lower()
        return w

    t0 = time.perf_counter()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Invalid api_key")

    # Validate required
    if not isinstance(headword, str) or not (1 <= len(headword) <= 128):
        return _err("VALIDATION_ERROR", "headword must be a string length 1..128")
    if not isinstance(normalized_headword, str) or not (1 <= len(normalized_headword) <= 128):
        return _err("VALIDATION_ERROR", "normalized_headword must be a string length 1..128")
    if language != "en":
        return _err("VALIDATION_ERROR", "Invalid language", allowed=["en"])
    if not isinstance(source, str) or len(source.strip()) == 0:
        return _err("VALIDATION_ERROR", "source must be a non-empty string")
    if pronunciation_ipa is not None and not isinstance(pronunciation_ipa, str):
        return _err("VALIDATION_ERROR", "pronunciation_ipa must be a string")
    if status is None:
        status = "active"
    if status not in ("active", "deprecated"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'deprecated'")

    # Enforce that normalized_headword matches service normalization rules
    expected_norm = _normalize_word(normalized_headword)
    if expected_norm != normalized_headword:
        return _err("VALIDATION_ERROR", "normalized_headword must already be normalized per service rules")

    entries = _load("lexicon_entries.json")

    # Uniqueness: unique(normalized_headword, language, source) where status != 'deleted'
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("status") != "deleted" and e.get("normalized_headword") == normalized_headword and e.get("language") == language and e.get("source") == source:
            return _err("CONFLICT", "Lexicon entry already exists for (normalized_headword, language, source)", existing_id=e.get("id"))

    now = _now_iso()
    new_id = "le_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    row = {
        "id": new_id,
        "headword": headword,
        "normalized_headword": normalized_headword,
        "language": language,
        "pronunciation_ipa": pronunciation_ipa,
        "source": source,
        "status": status,
        "created_at": now,
        "updated_at": now
    }
    entries.append(row)
    _save("lexicon_entries.json", entries)

    # Operational logging
    reqs = _load("definition_requests.json")
    req_id = "dr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
    reqs.append({
        "id": req_id,
        "word_raw": "__create_lexicon_entry__",
        "word_normalized": "__create_lexicon_entry__",
        "language": "en",
        "matched_entry_id": new_id,
        "result_count": 1,
        "cache_status": "bypass",
        "latency_ms": latency_ms,
        "status": "succeeded",
        "error_message": None,
        "request_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now
    })
    _save("definition_requests.json", reqs)

    return {"entry": row}

def update_lexicon_entry(api_key, id, headword=None, normalized_headword=None, language=None, pronunciation_ipa=None, source=None, status=None, **_extra):
    import json, os, datetime, time, unicodedata, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0471000" if __import__("os").path.isdir("./environment_mix/0471000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _normalize_word(w):
        w = unicodedata.normalize("NFKC", w)
        w = w.strip()
        w = re.sub(r"\s+", " ", w)
        w = w.lower()
        return w

    t0 = time.perf_counter()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Invalid api_key")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # Validate optional fields
    if headword is not None and (not isinstance(headword, str) or not (1 <= len(headword) <= 128)):
        return _err("VALIDATION_ERROR", "headword must be a string length 1..128")
    if normalized_headword is not None and (not isinstance(normalized_headword, str) or not (1 <= len(normalized_headword) <= 128)):
        return _err("VALIDATION_ERROR", "normalized_headword must be a string length 1..128")
    if language is not None and language != "en":
        return _err("VALIDATION_ERROR", "Invalid language", allowed=["en"])
    if pronunciation_ipa is not None and not isinstance(pronunciation_ipa, str):
        return _err("VALIDATION_ERROR", "pronunciation_ipa must be a string")
    if source is not None and (not isinstance(source, str) or not source.strip()):
        return _err("VALIDATION_ERROR", "source must be a non-empty string")
    if status is not None and status not in ("active", "deprecated", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status", allowed=["active", "deprecated", "deleted"])

    entries = _load("lexicon_entries.json")
    idx = None
    for i, e in enumerate(entries):
        if isinstance(e, dict) and e.get("id") == id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Lexicon entry not found", id=id)

    row = entries[idx]
    old_status = row.get("status")

    # Enforce terminal deleted
    if old_status == "deleted":
        # no transitions out of deleted
        if status is not None and status != "deleted":
            return _err("INVALID_TRANSITION", "Cannot transition from deleted", from_status="deleted", to_status=status)
        # allow only non-status updates? Business rule says once deleted never transition back; doesn't forbid metadata edits,
        # but schema lifecycle implies deleted is terminal; treat any update as invalid to avoid resurrecting/altering deleted rows.
        if any(v is not None for v in [headword, normalized_headword, language, pronunciation_ipa, source]):
            return _err("INVALID_TRANSITION", "Cannot modify a deleted entry", id=id)

    # Normalize rule for normalized_headword if provided
    if normalized_headword is not None:
        expected_norm = _normalize_word(normalized_headword)
        if expected_norm != normalized_headword:
            return _err("VALIDATION_ERROR", "normalized_headword must already be normalized per service rules")

    # Status transition validation
    if status is not None and status != old_status:
        transitions = {
            "active": ["deprecated", "deleted"],
            "deprecated": ["active", "deleted"],
            "deleted": []
        }
        allowed = transitions.get(old_status, [])
        if status not in allowed:
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=old_status, to_status=status)

    # Apply updates to a copy then validate uniqueness
    new_row = dict(row)
    if headword is not None:
        new_row["headword"] = headword
    if normalized_headword is not None:
        new_row["normalized_headword"] = normalized_headword
    if language is not None:
        new_row["language"] = language
    if pronunciation_ipa is not None:
        new_row["pronunciation_ipa"] = pronunciation_ipa
    if source is not None:
        new_row["source"] = source
    if status is not None:
        new_row["status"] = status

    # Constraints lengths (re-check after changes)
    if not isinstance(new_row.get("headword"), str) or not (1 <= len(new_row["headword"]) <= 128):
        return _err("VALIDATION_ERROR", "headword must be a string length 1..128")
    if not isinstance(new_row.get("normalized_headword"), str) or not (1 <= len(new_row["normalized_headword"]) <= 128):
        return _err("VALIDATION_ERROR", "normalized_headword must be a string length 1..128")

    # Uniqueness among non-deleted entries
    if new_row.get("status") != "deleted":
        for e in entries:
            if not isinstance(e, dict) or e.get("id") == id:
                continue
            if e.get("status") != "deleted" and e.get("normalized_headword") == new_row.get("normalized_headword") and e.get("language") == new_row.get("language") and e.get("source") == new_row.get("source"):
                return _err("CONFLICT", "Uniqueness constraint violated for (normalized_headword, language, source)", conflicting_id=e.get("id"))

    # Persist
    now = _now_iso()
    new_row["updated_at"] = now
    entries[idx] = new_row
    _save("lexicon_entries.json", entries)

    # Operational logging
    reqs = _load("definition_requests.json")
    req_id = "dr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
    reqs.append({
        "id": req_id,
        "word_raw": "__update_lexicon_entry__",
        "word_normalized": "__update_lexicon_entry__",
        "language": "en",
        "matched_entry_id": id,
        "result_count": 1,
        "cache_status": "bypass",
        "latency_ms": latency_ms,
        "status": "succeeded",
        "error_message": None,
        "request_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now
    })
    _save("definition_requests.json", reqs)

    return {"entry": new_row}

def create_entry_sense(api_key, entry_id, part_of_speech, definition, sense_order, definition_plain=None, labels=None, source_ref=None, status=None, **_extra):
    import json, os, datetime, time, secrets, unicodedata

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0471000" if __import__("os").path.isdir("./environment_mix/0471000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # -------- auth (api_key is required by tool schema, but store has no auth collections) --------
    # Per contract: authenticate only against a credential row's client-visible value or its id.
    # If no auth store exists, do NOT reject well-formed calls: accept any non-empty api_key.
    def _auth(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, None
        k = api_key_value.strip()
        auth_files = ["api_keys.json", "credentials.json", "keys.json", "callers.json", "users.json"]
        any_auth_data = False
        for fn in auth_files:
            rows = _load(fn)
            if isinstance(rows, list) and rows:
                any_auth_data = True
                for r in rows:
                    if not isinstance(r, dict):
                        continue
                    candidates = [r.get("id"), r.get("api_key"), r.get("key"), r.get("value"), r.get("token"), r.get("client_key"), r.get("name")]
                    if any(isinstance(c, str) and c == k for c in candidates):
                        st = r.get("status") or r.get("state")
                        if st in (None, "active", "enabled", "ok"):
                            return r, fn
        if not any_auth_data:
            return {"id": k, "api_key": k, "status": "active"}, None
        return None, None

    authed, auth_file_used = _auth(api_key)
    if authed is None:
        # If an auth store exists and no match was found, reject.
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # -------- input validation --------
    if not isinstance(entry_id, str) or not entry_id.strip():
        return _err("VALIDATION_ERROR", "entry_id must be a non-empty string.", field="entry_id")
    entry_id = entry_id.strip()

    if not isinstance(part_of_speech, str) or not part_of_speech.strip():
        return _err("VALIDATION_ERROR", "part_of_speech must be a non-empty string.", field="part_of_speech")
    part_of_speech = part_of_speech.strip()
    allowed_pos = {"noun", "verb", "adjective", "adverb", "pronoun", "preposition", "conjunction", "interjection", "determiner", "numeral", "particle", "other"}
    # Tool schema says minLength 1 (not enum), but backend schema has an enum; enforce it.
    if part_of_speech not in allowed_pos:
        return _err("VALIDATION_ERROR", "Invalid part_of_speech.", field="part_of_speech", allowed=sorted(allowed_pos))

    if not isinstance(definition, str) or not definition.strip():
        return _err("VALIDATION_ERROR", "definition must be a non-empty string.", field="definition")
    definition = definition.strip()
    if len(definition) < 1 or len(definition) > 4000:
        return _err("VALIDATION_ERROR", "definition length must be between 1 and 4000.", field="definition", rule="definition length between 1 and 4000")

    if definition_plain is not None:
        if not isinstance(definition_plain, str):
            return _err("VALIDATION_ERROR", "definition_plain must be a string when provided.", field="definition_plain")
        definition_plain = definition_plain.strip()
        if definition_plain == "":
            definition_plain = None

    if not isinstance(sense_order, int):
        return _err("VALIDATION_ERROR", "sense_order must be an integer.", field="sense_order")
    if sense_order < 1:
        return _err("VALIDATION_ERROR", "sense_order must be >= 1.", field="sense_order", rule="sense_order >= 1")

    if labels is None:
        labels = []
    if not isinstance(labels, list):
        return _err("VALIDATION_ERROR", "labels must be an array of strings.", field="labels")
    norm_labels = []
    for i, it in enumerate(labels):
        if not isinstance(it, str):
            return _err("VALIDATION_ERROR", "Each label must be a string.", field="labels", index=i)
        s = it.strip()
        if s == "":
            continue
        norm_labels.append(s)
    labels = norm_labels

    if source_ref is not None:
        if not isinstance(source_ref, str):
            return _err("VALIDATION_ERROR", "source_ref must be a string when provided.", field="source_ref")
        source_ref = source_ref.strip()
        if source_ref == "":
            source_ref = None

    if status is None:
        status = "active"
    if not isinstance(status, str):
        return _err("VALIDATION_ERROR", "status must be a string.", field="status")
    status = status.strip()
    if status not in ("active", "deprecated"):
        return _err("VALIDATION_ERROR", "Invalid status; must be 'active' or 'deprecated'.", field="status", allowed=["active", "deprecated"])

    # -------- load datastore --------
    entries = _load("lexicon_entries.json")
    senses = _load("entry_senses.json")
    requests = _load("definition_requests.json")

    if not isinstance(entries, list):
        entries = []
    if not isinstance(senses, list):
        senses = []
    if not isinstance(requests, list):
        requests = []

    # -------- foreign key validation: entry must exist (and not be deleted) --------
    parent = None
    for e in entries:
        if isinstance(e, dict) and e.get("id") == entry_id:
            parent = e
            break
    if parent is None:
        return _err("NOT_FOUND", "lexicon entry not found.", entry_id=entry_id)
    if parent.get("status") == "deleted":
        # FK exists but is terminal-deleted; treat as not found for creation under it.
        return _err("NOT_FOUND", "lexicon entry is deleted.", entry_id=entry_id)

    # -------- uniqueness: unique(entry_id, sense_order) where status != 'deleted' --------
    for s in senses:
        if not isinstance(s, dict):
            continue
        if s.get("entry_id") == entry_id and s.get("sense_order") == sense_order and s.get("status") != "deleted":
            return _err(
                "CONFLICT",
                "Uniqueness constraint violated: (entry_id, sense_order) must be unique among non-deleted senses.",
                rule="unique(entry_id, sense_order) where status != 'deleted'",
                entry_id=entry_id,
                sense_order=sense_order,
                conflicting_id=s.get("id"),
            )

    # -------- id generation consistent with existing ids --------
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(26))

    existing_ids = {r.get("id") for r in senses if isinstance(r, dict) and isinstance(r.get("id"), str)}
    new_id = _gen_id("sen")
    # Avoid rare collision
    for _ in range(10):
        if new_id not in existing_ids:
            break
        new_id = _gen_id("sen")
    if new_id in existing_ids:
        return _err("CONFLICT", "Could not allocate a unique id for the new sense.", rule="primary_key(id) unique")

    new_row = {
        "id": new_id,
        "entry_id": entry_id,
        "part_of_speech": part_of_speech,
        "definition": definition,
        "definition_plain": definition_plain,
        "sense_order": sense_order,
        "labels": labels,
        "source_ref": source_ref,
        "status": status,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    senses.append(new_row)
    _save("entry_senses.json", senses)

    # -------- operational logging: append one definition_requests row per invocation --------
    # No official tool exists for mutations in schema, but business rules require operational logging collection be used.
    # Use cache_status='bypass' and status='succeeded' for this mutation.
    def _norm_word(x):
        x = "" if x is None else str(x)
        x = unicodedata.normalize("NFKC", x).strip().lower()
        return x

    def _gen_req_id():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "req_" + "".join(secrets.choice(alphabet) for _ in range(26))

    req_id = _gen_req_id()
    existing_req_ids = {r.get("id") for r in requests if isinstance(r, dict) and isinstance(r.get("id"), str)}
    for _ in range(10):
        if req_id not in existing_req_ids:
            break
        req_id = _gen_req_id()

    latency_ms = max(0, int(round((time.time() - t0) * 1000)))
    req_row = {
        "id": req_id,
        "word_raw": f"create_entry_sense:{entry_id}",
        "word_normalized": _norm_word(f"create_entry_sense:{entry_id}"),
