def create_sense_example(api_key, sense_id, example_text, example_order, source_ref=None, status=None, **_extra):
    import json, os, datetime, time, secrets, unicodedata

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0471000" if __import__("os").path.isdir("./environment_mix/0471000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # -------- auth --------
    def _auth(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, None
        k = api_key_value.strip()
        auth_files = ["api_keys.json", "credentials.json", "keys.json", "callers.json", "users.json"]
        any_auth_data = False
        for fn in auth_files:
            rows = _load(fn)
            if isinstance(rows, list) and rows:
                any_auth_data = True
                for r in rows:
                    if not isinstance(r, dict):
                        continue
                    candidates = [r.get("id"), r.get("api_key"), r.get("key"), r.get("value"), r.get("token"), r.get("client_key"), r.get("name")]
                    if any(isinstance(c, str) and c == k for c in candidates):
                        st = r.get("status") or r.get("state")
                        if st in (None, "active", "enabled", "ok"):
                            return r, fn
        if not any_auth_data:
            return {"id": k, "api_key": k, "status": "active"}, None
        return None, None

    authed, auth_file_used = _auth(api_key)
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # -------- input validation --------
    if not isinstance(sense_id, str) or not sense_id.strip():
        return _err("VALIDATION_ERROR", "sense_id must be a non-empty string.", field="sense_id")
    sense_id = sense_id.strip()

    if not isinstance(example_text, str) or not example_text.strip():
        return _err("VALIDATION_ERROR", "example_text must be a non-empty string.", field="example_text")
    example_text = example_text.strip()
    if len(example_text) < 1 or len(example_text) > 2000:
        return _err("VALIDATION_ERROR", "example_text length must be between 1 and 2000.", field="example_text", rule="example_text length between 1 and 2000")

    if not isinstance(example_order, int):
        return _err("VALIDATION_ERROR", "example_order must be an integer.", field="example_order")
    if example_order < 1:
        return _err("VALIDATION_ERROR", "example_order must be >= 1.", field="example_order", rule="example_order >= 1")

    if source_ref is not None:
        if not isinstance(source_ref, str):
            return _err("VALIDATION_ERROR", "source_ref must be a string when provided.", field="source_ref")
        source_ref = source_ref.strip()
        if source_ref == "":
            source_ref = None

    if status is None:
        status = "active"
    if not isinstance(status, str):
        return _err("VALIDATION_ERROR", "status must be a string.", field="status")
    status = status.strip()
    if status not in ("active", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status; must be 'active' or 'deleted'.", field="status", allowed=["active", "deleted"])

    # -------- load datastore --------
    senses = _load("entry_senses.json")
    examples = _load("sense_examples.json")
    requests = _load("definition_requests.json")

    if not isinstance(senses, list):
        senses = []
    if not isinstance(examples, list):
        examples = []
    if not isinstance(requests, list):
        requests = []

    # -------- foreign key validation: sense must exist and not be deleted --------
    parent = None
    for s in senses:
        if isinstance(s, dict) and s.get("id") == sense_id:
            parent = s
            break
    if parent is None:
        return _err("NOT_FOUND", "sense not found.", sense_id=sense_id)
    if parent.get("status") == "deleted":
        return _err("NOT_FOUND", "sense is deleted.", sense_id=sense_id)

    # -------- uniqueness: unique(sense_id, example_order) where status != 'deleted' --------
    for ex in examples:
        if not isinstance(ex, dict):
            continue
        if ex.get("sense_id") == sense_id and ex.get("example_order") == example_order and ex.get("status") != "deleted":
            return _err(
                "CONFLICT",
                "Uniqueness constraint violated: (sense_id, example_order) must be unique among non-deleted examples.",
                rule="unique(sense_id, example_order) where status != 'deleted'",
                sense_id=sense_id,
                example_order=example_order,
                conflicting_id=ex.get("id"),
            )

    # -------- create --------
    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(26))

    existing_ids = {r.get("id") for r in examples if isinstance(r, dict) and isinstance(r.get("id"), str)}
    new_id = _gen_id("exm")
    for _ in range(10):
        if new_id not in existing_ids:
            break
        new_id = _gen_id("exm")
    if new_id in existing_ids:
        return _err("CONFLICT", "Could not allocate a unique id for the new example.", rule="primary_key(id) unique")

    new_row = {
        "id": new_id,
        "sense_id": sense_id,
        "example_text": example_text,
        "example_order": example_order,
        "source_ref": source_ref,
        "status": status,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    examples.append(new_row)
    _save("sense_examples.json", examples)

    # -------- operational logging --------
    def _norm_word(x):
        x = "" if x is None else str(x)
        x = unicodedata.normalize("NFKC", x).strip().lower()
        return x

    def _gen_req_id():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "req_" + "".join(secrets.choice(alphabet) for _ in range(26))

    req_id = _gen_req_id()
    existing_req_ids = {r.get("id") for r in requests if isinstance(r, dict) and isinstance(r.get("id"), str)}
    for _ in range(10):
        if req_id not in existing_req_ids:
            break
        req_id = _gen_req_id()

    latency_ms = max(0, int(round((time.time() - t0) * 1000)))
    req_row = {
        "id": req_id,
        "word_raw": f"create_sense_example:{sense_id}",
        "word_normalized": _norm_word(f"create_sense_example:{sense_id}"),
        "language": "en",
        "matched_entry_id": None,
        "result_count": 1,
        "cache_status": "bypass",
        "latency_ms": latency_ms,
        "status": "succeeded",
        "error_message": None,
        "request_ip": None,
        "user_agent": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    requests.append(req_row)
    _save("definition_requests.json", requests)

    return {"example": new_row}

def get_caller_profile(api_key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0471000" if __import__("os").path.isdir("./environment_mix/0471000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    k = api_key.strip()

    # Authenticate by matching client-visible value OR id; choose any active match across plausible auth files.
    auth_files = ["credentials.json", "api_keys.json", "keys.json", "callers.json", "users.json"]
    any_auth_data = False
    authed = None
    auth_file_used = None
    for fn in auth_files:
        rows = _load(fn)
        if isinstance(rows, list) and rows:
            any_auth_data = True
            for r in rows:
                if not isinstance(r, dict):
                    continue
                candidates = [
                    r.get("api_key"), r.get("key"), r.get("value"), r.get("token"),
                    r.get("secret"), r.get("client_key"), r.get("client_secret"),
                    r.get("name"), r.get("id"),
                ]
                if any(isinstance(c, str) and c == k for c in candidates):
                    st = r.get("status") or r.get("state")
                    if st in (None, "active", "enabled", "ok"):
                        authed = r
                        auth_file_used = fn
                        break
            if authed is not None:
                break

    # If there are auth rows but no match, it's unauthorized.
    if any_auth_data and authed is None:
        # Still allow the special case where api_key equals a known lexicon source (common in this datastore).
        entries = _load("lexicon_entries.json")
        if not isinstance(entries, list):
            entries = []
        sources = {e.get("source") for e in entries if isinstance(e, dict)}
        if k not in sources:
            # log call (rate-limit accounting uses definition_requests)
            reqs = _load("definition_requests.json")
            if not isinstance(reqs, list):
                reqs = []
            latency_ms = max(0, int((time.time() - t0) * 1000))
            reqs.append({
                "id": f"req_{int(time.time()*1000)}",
                "word_raw": "__get_caller_profile__",
                "word_normalized": "__get_caller_profile__",
                "language": "en",
                "matched_entry_id": None,
                "result_count": 0,
                "cache_status": "bypass",
                "latency_ms": latency_ms,
                "status": "failed",
                "error_message": "UNAUTHORIZED",
                "request_ip": None,
                "user_agent": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            })
            _save("definition_requests.json", reqs)
            return _err("UNAUTHORIZED", "Invalid api_key.")

    if not any_auth_data and authed is None:
        authed = {"id": k, "api_key": k, "status": "active"}
        auth_file_used = None
    if authed is None:
        # matched as lexicon source fallback
        authed = {"id": k, "api_key": k, "status": "active", "kind": "source-key"}
        auth_file_used = "lexicon_entries.json(source)"

    # Quota/rate status derived from definition_requests: 60 rpm soft rate limit; 10k/day quota.
    reqs = _load("definition_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    def _parse_dt(x):
        if not isinstance(x, str) or not x:
            return None
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(x).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    last_min_cutoff = now - datetime.timedelta(seconds=60)
    day_cutoff = now - datetime.timedelta(days=1)

    # These logs don't store api_key; compute global observed usage (best possible with schema given).
    reqs_last_min = 0
    reqs_last_day = 0
    for r in reqs:
        if not isinstance(r, dict):
            continue
        dt = _parse_dt(r.get("created_at")) or _parse_dt(r.get("updated_at"))
        if dt is None:
            continue
        if dt >= last_min_cutoff:
            reqs_last_min += 1
        if dt >= day_cutoff:
            reqs_last_day += 1

    rate_limit_per_min = 60
    quota_per_day = 10000

    rate_remaining = max(0, rate_limit_per_min - reqs_last_min)
    quota_remaining = max(0, quota_per_day - reqs_last_day)

    latency_ms = max(0, int((time.time() - t0) * 1000))

    # operational logging: one definition_requests row per tool invocation
    reqs.append({
        "id": f"req_{int(time.time()*1000)}",
        "word_raw": "__get_caller_profile__",
        "word_normalized": "__get_caller_profile__",
        "language": "en",
        "matched_entry_id": None,
        "result_count": 1,
        "cache_status": "bypass",
        "latency_ms": latency_ms,
        "status": "succeeded",
        "error_message": None,
        "request_ip": None,
        "user_agent": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("definition_requests.json", reqs)

    return {
        "caller": {
            "id": authed.get("id") or k,
            "api_key": k,
            "status": authed.get("status", "active"),
            "authenticated_via": auth_file_used,
        },
        "scopes": authed.get("scopes") if isinstance(authed.get("scopes"), list) else ["dictionary:read", "dictionary:write"],
        "rate_limit": {
            "limit_per_min": rate_limit_per_min,
            "used_last_min": reqs_last_min,
            "remaining": rate_remaining,
            "reset_in_seconds": 60,
        },
        "quota": {
            "limit_per_day": quota_per_day,
            "used_last_day": reqs_last_day,
            "remaining": quota_remaining,
        },
        "meta": {"latency_ms": latency_ms},
    }
